-- Phase 95 rehearsal · tests phase95-no-vat-no-custom-amount.sql on the real database WITHOUT saving anything.
-- GENERATED by scripts/build-rehearsal.sh — edit the migration or tests/phase95-*.sql instead.
-- Run this whole file at once in the Supabase SQL editor. It ends with an error on purpose: that cancels
-- everything. Expected last line: ERROR: REHEARSAL REPORT (nothing was saved) … with PASS/FAIL for each check.

-- ===== setup =====
-- Phase 95 setup (runs BEFORE the migration in phase95-rehearsal.sql): three pretend orders that still have VAT.
create temp table rehearsal_ids(k text primary key, id uuid, v numeric);
create temp table rehearsal_payload(p jsonb);
do $setup$
declare customer_id uuid; v public.product_variants; slot_id uuid; method text; res jsonb; pay jsonb; ord public.orders; a public.order_payment_attempts; prepared_id uuid; checking_id uuid;
begin
  select ur.user_id into customer_id from public.user_roles ur where ur.role = 'customer' order by ur.created_at limit 1;
  select pv.* into v from public.product_variants pv join public.products pr on pr.id = pv.product_id left join public.categories c on c.id = pr.category_id
   where pv.is_active and pv.min_qty <= 1 and pr.status = 'active' and pr.kind = 'standard' and not coalesce(pr.is_test_product, false)
     and (pr.category_id is null or c.is_active) order by pv.price desc limit 1;
  select s.id into slot_id from public.availability_slots s where s.is_open and s.starts_at > now() + interval '3 days'
     and (select count(*) from public.orders o where o.slot_id = s.id and o.status <> 'cancelled') < s.capacity order by s.starts_at limit 1;
  select code into method from public.payment_methods where active and code <> 'paymongo' order by code limit 1;
  pay := jsonb_build_object('name', 'Rehearsal', 'phone', '09171234567', 'slot_id', slot_id, 'notes', 'phase 95 rehearsal', 'payment_method', method,
    'items', jsonb_build_array(jsonb_build_object('variant_id', v.id, 'qty', 1)));
  insert into rehearsal_payload values (pay);
  insert into rehearsal_ids values ('customer', customer_id, null);
  perform set_config('request.jwt.claim.sub', customer_id::text, true);
  perform set_config('request.jwt.claims', json_build_object('sub', customer_id, 'role', 'authenticated')::text, true);
  -- orders placed while VAT was still on (the old default)
  alter table public.orders alter column vat_rate set default 0.12;
  foreach method in array array['unpaid', 'prepared', 'checking'] loop
    perform set_config('role', 'authenticated', true);
    res := public.create_order(pay || jsonb_build_object('request_id', gen_random_uuid(), 'fulfillment', 'pickup'));
    perform set_config('role', 'postgres', true);
    select * into ord from public.orders where id = (res->>'id')::uuid;
    insert into rehearsal_ids values (method, ord.id, ord.total_amount);
  end loop;
  update public.orders set status = 'confirmed' where id in (select id from rehearsal_ids where k in ('prepared', 'checking'));
  select id into prepared_id from rehearsal_ids where k = 'prepared'; select id into checking_id from rehearsal_ids where k = 'checking';
  perform set_config('role', 'authenticated', true);
  perform public.start_order_payment(prepared_id, pay->>'payment_method', 'downpayment', null);
  a := public.start_order_payment(checking_id, pay->>'payment_method', 'downpayment', null);
  perform set_config('role', 'postgres', true);
  update public.order_payment_attempts set status = 'verification_pending', submitted_at = now(), transaction_reference = '1234567890',
    proof_storage_path = 'rehearsal/receipt.jpg' where id = a.id;
end $setup$;
-- fire the checks that normally wait for the end of the transaction, so the migration can alter the table
set constraints all immediate;

-- ===== phase 95 =====
-- Phase 95 · No VAT, and no "Pay a different amount".
--
-- Why: LexC's is not VAT-registered, so VAT must not be charged. And customers now pay either the downpayment or the
-- full amount (the "different amount" choice from phase 78 is removed).
--
-- What it does:
--   1. New orders get vat_rate 0, so no VAT is added (the VAT step from phase 77 stays and simply adds ₱0).
--   2. Orders not paid yet lose their VAT now: total, downpayment and the reservation record are recalculated. An
--      order counts as "not paid yet" when no money was received and no receipt is being checked. If the customer
--      already prepared a payment but sent nothing, that prepared amount is corrected too. PayMongo payments that were
--      already started are left alone; their orders keep their VAT, and the notice at the end lists them.
--   3. Orders where money was received, or a receipt is being checked, keep their amounts exactly as they were.
--   4. start_order_payment accepts only "downpayment" or "full" (the custom amount is refused).
--
-- What it does NOT do: change prices, the 60% downpayment rate, the rush fee, the delivery fee, payments already
-- made, or any paid order.
--
-- Apply AFTER phase 94. Rehearse with database/tests/phase95-rehearsal.sql (rolls itself back), then run this whole
-- file once in the Supabase SQL editor. Safe to re-run.

alter table public.orders alter column vat_rate set default 0;

-- 1. orders not paid yet: no VAT. The phase 77 VAT step recalculates the downpayment when the total changes.
with fixable as (
  select o.id from public.orders o
  where o.vat_amount > 0 and o.amount_paid = 0 and o.status not in ('cancelled', 'completed')
    and not exists (select 1 from public.order_payment_attempts a
                    where a.order_id = o.id and (a.status in ('verification_pending', 'paid')
                      or (a.status = 'awaiting_payment' and (a.provider_checkout_id is not null or a.provider_payment_id is not null))))
)
update public.orders o set vat_rate = 0, total_amount = o.total_amount - o.vat_amount
from fixable f where o.id = f.id;

-- a payment prepared for one of those orders (nothing sent yet) asks for the new amount
update public.order_payment_attempts a
set amount = case when a.payment_kind = 'full' or o.deposit_due >= o.total_amount then o.total_amount else o.deposit_due end
from public.orders o
where a.order_id = o.id and a.status = 'awaiting_payment' and o.vat_rate = 0 and o.amount_paid = 0
  and a.provider_checkout_id is null and a.provider_payment_id is null
  and a.amount <> case when a.payment_kind = 'full' or o.deposit_due >= o.total_amount then o.total_amount else o.deposit_due end;

-- 2. no more custom amounts
do $$
declare def text := pg_get_functiondef('private.start_order_payment(uuid,text,text,numeric)'::regprocedure);
  old_check text := 'if pay_option is not null and pay_option not in (''downpayment'',''full'',''custom'') then
    raise exception ''Choose downpayment, full payment, or your own amount.'' using errcode=''22023'';';
  new_check text := 'if pay_option is not null and pay_option not in (''downpayment'',''full'') then
    raise exception ''Choose the downpayment or the full payment.'' using errcode=''22023'';';
begin
  if position(new_check in def) > 0 then return; end if;            -- already applied
  if position(old_check in def) = 0 then
    raise exception 'private.start_order_payment is not the expected version; review before applying phase 95.';
  end if;
  execute replace(def, old_check, new_check);
end $$;

-- 3. what still carries VAT (paid or being paid) — for the owner's records
do $$
declare n int; list text;
begin
  select count(*), string_agg('#' || order_number, ', ' order by order_number) into n, list
  from public.orders where vat_amount > 0 and status not in ('cancelled');
  raise notice 'Orders that keep their VAT because money was received or is being checked: % %', n, coalesce(list, '');
end $$;


-- ===== checks =====
-- Phase 95 checks (after the migration in phase95-rehearsal.sql). Builds pretend orders BEFORE the migration runs
-- (see the "setup" block in the rehearsal), then checks them. Ends with an error on purpose: nothing is saved.
do $rehearsal$
declare report text := ''; ok boolean; o public.orders; a public.order_payment_attempts; res jsonb; customer_id uuid; pay jsonb;
begin
  -- 1. an order nobody paid yet: VAT removed, downpayment recalculated
  select * into o from public.orders where id = (select id from rehearsal_ids where k = 'unpaid');
  ok := o.vat_amount = 0 and o.vat_rate = 0 and o.total_amount = o.items_subtotal + o.customization_total + o.delivery_fee + o.rush_fee
    and o.deposit_due = round((o.total_amount - case when o.delivery_in_deposit then o.delivery_fee else 0 end) * o.deposit_rate, 2) + case when o.delivery_in_deposit then o.delivery_fee else 0 end;
  report := report || E'\n' || case when ok then 'PASS' else 'FAIL' end || format('  unpaid order: VAT ₱%s, total ₱%s, downpayment ₱%s', o.vat_amount, o.total_amount, o.deposit_due);
  ok := (select order_total from public.booking_entries where order_id = o.id) = o.total_amount;
  report := report || E'\n' || case when ok then 'PASS' else 'FAIL' end || '  the reservation record shows the new total';

  -- 2. a prepared payment (nothing sent) asks for the new amount
  select * into o from public.orders where id = (select id from rehearsal_ids where k = 'prepared');
  select * into a from public.order_payment_attempts where order_id = o.id and status = 'awaiting_payment';
  ok := o.vat_amount = 0 and a.amount = o.deposit_due;
  report := report || E'\n' || case when ok then 'PASS' else 'FAIL' end || format('  prepared payment: now asks ₱%s (downpayment ₱%s)', a.amount, o.deposit_due);

  -- 3. an order with a receipt being checked keeps its amounts
  select * into o from public.orders where id = (select id from rehearsal_ids where k = 'checking');
  ok := o.vat_amount > 0 and o.total_amount = (select v from rehearsal_ids where k = 'checking');
  report := report || E'\n' || case when ok then 'PASS' else 'FAIL' end || format('  receipt being checked: unchanged (VAT ₱%s kept)', o.vat_amount);

  -- 4. new orders: no VAT
  customer_id := (select id from rehearsal_ids where k = 'customer');
  pay := (select p from rehearsal_payload);   -- read before switching to the customer role
  perform set_config('request.jwt.claim.sub', customer_id::text, true);
  perform set_config('request.jwt.claims', json_build_object('sub', customer_id, 'role', 'authenticated')::text, true); perform set_config('role', 'authenticated', true);
  res := public.create_order(pay || jsonb_build_object('request_id', gen_random_uuid(), 'fulfillment', 'pickup'));
  perform set_config('role', 'postgres', true);
  select * into o from public.orders where id = (res->>'id')::uuid;
  ok := o.vat_rate = 0 and o.vat_amount = 0 and o.total_amount = o.items_subtotal + o.customization_total + o.rush_fee and o.deposit_due = round(o.total_amount * o.deposit_rate, 2);
  report := report || E'\n' || case when ok then 'PASS' else 'FAIL' end || format('  new order: VAT ₱%s, total ₱%s, downpayment ₱%s (60%%)', o.vat_amount, o.total_amount, o.deposit_due);

  -- 5. "different amount" is refused; downpayment and full still work
  update public.orders set status = 'confirmed' where id = o.id;
  perform set_config('role', 'authenticated', true);
  begin perform public.start_order_payment(o.id, (select code from public.payment_methods where active and code <> 'paymongo' order by code limit 1), 'custom', 10);
    report := report || E'\nFAIL  a custom amount was accepted';
  exception when others then report := report || E'\nPASS  a custom amount is refused (' || sqlerrm || ')'; end;
  a := public.start_order_payment(o.id, (select code from public.payment_methods where active and code <> 'paymongo' order by code limit 1), 'downpayment', null);
  ok := a.amount = o.deposit_due;
  a := public.start_order_payment(o.id, (select code from public.payment_methods where active and code <> 'paymongo' order by code limit 1), 'full', null);
  ok := ok and a.amount = o.total_amount;
  perform set_config('role', 'postgres', true);
  report := report || E'\n' || case when ok then 'PASS' else 'FAIL' end || '  downpayment and full payment still work';

  raise exception 'REHEARSAL REPORT (nothing was saved — this error undoes everything):%', report;
end $rehearsal$;
